window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-14591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3352 na letra ε · nº geral 14591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sair do porto; ganhar o mar 2 sair; afastar-se, ἐκ e gen. 〈ἔξορμος〉</p></section></article>\n<article id=\"entry-dgp-14592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3353 na letra ε · nº geral 14592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir (barco) para fora de, ἐκ e gen. 2 lançar ao mar ♦ méd. 3 impelir adiante 4 fazer-se ao largo.</p></section></article>\n<article id=\"entry-dgp-14593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξορμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3354 na letra ε · nº geral 14593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que deixou o porto; que ganhou o mar. 〈ἐξ, ὅρμος〉</p></section></article>\n<article id=\"entry-dgp-14594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορύσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 3355 na letra ε · nº geral 14594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -ύττω 1 desenterrar; arrancar ♦ méd. 2 escavar (trincheira).</p></section></article>\n<article id=\"entry-dgp-14595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξορχέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3356 na letra ε · nº geral 14595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dançar até o fim 2 saltar fora de; evadir-se 3 dançar fora (do rito); transgredir; desdenhar (da verdade) 4 divulgar por meio de pantomina dançada (segredos, mistérios) 5 parodiar; debochar.</p></section></article>\n<article id=\"entry-dgp-14596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοσιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3357 na letra ε · nº geral 14596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dedicar; consagrar ♦ méd. 2 afastar com sacrifícios expiatórios.</p></section></article>\n<article id=\"entry-dgp-14597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοστρακίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3358 na letra ε · nº geral 14597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 banir (por ostracismo) 2 banir.</p></section></article>\n<article id=\"entry-dgp-14598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοστρακισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3359 na letra ε · nº geral 14598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banimento (por ostracismo). 〈ἐξοσ­τρακίζω〉</p></section></article>\n<article id=\"entry-dgp-14599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοτρύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3360 na letra ε · nº geral 14599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estimular; provocar; excitar com vigor alguém, ac., a algo, ἐπί e ac. ou inf.</p></section></article>\n<article id=\"entry-dgp-14600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουδενέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3361 na letra ε · nº geral 14600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐξουδενίζω.</p></section></article>\n<article id=\"entry-dgp-14601\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουδενίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3362 na letra ε · nº geral 14601</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">não ter em conta; desprezar. 〈ἐξ, οὐδείς〉</p></section></article>\n<article id=\"entry-dgp-14602\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουδενόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3363 na letra ε · nº geral 14602</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐξουδενίζω.</p></section></article>\n<article id=\"entry-dgp-14603\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουθενέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3364 na letra ε · nº geral 14603</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐξουδενέω.</p></section></article>\n<article id=\"entry-dgp-14604\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουθενόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3365 na letra ε · nº geral 14604</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. = ἐξουδενέω.</p></section></article>\n<article id=\"entry-dgp-14605\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3366 na letra ε · nº geral 14605</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excretar pela urina; urinar.</p></section></article>\n<article id=\"entry-dgp-14606\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3367 na letra ε · nº geral 14606</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 liberdade; permissão; faculdade; poder de, gen. ou inf.: ἐ. ποιεῖν τινι plat. dar a alguém a liberdade ou o meio de fazer algo 2 poder; cargo; magistratura 3 autoridade; magistrado: οἱ ἐν ἐξουσίᾳ ὄντες artt. os magistrados 4 prepotência; arbítrio; arrogância 5 abundância de recursos; opulência 6 fausto; brilho; esplendor. 〈ἔξειμι1〉</p></section></article>\n<article id=\"entry-dgp-14607\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3368 na letra ε · nº geral 14607</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ter poder, autoridade sobre alguém, gen. 2 dar a alguém, dat., poder de, gen. ♦ pas. 3 ser submetido à autoridade de.</p></section></article>\n<article id=\"entry-dgp-14608\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξουσιαστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3369 na letra ε · nº geral 14608</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">autoritário; imperioso; impositivo. 〈ἐξουσιάζω〉</p></section></article>\n<article id=\"entry-dgp-14609\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοφέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 3370 na letra ε · nº geral 14609</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. 3ª sing. ἐξώφελλεν) aumentar cada vez mais.</p></section></article>\n<article id=\"entry-dgp-14610\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξοχα</h1><div class=\"entry-meta\"><span>DGP · ordem 3371 na letra ε · nº geral 14610</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. cf. ἔξοχος.</p></section></article>\n<article id=\"entry-dgp-14611\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοχή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3372 na letra ε · nº geral 14611</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 proeminência; saliência 2 excelência; superioridade: οἱ κατ᾽ ἐξοχήν n.t. as principais personagens, κατ᾽ ἐξοχήν por excelência, principalmente 3 Medic. excrescência; tumor. 〈ἐξέχω〉</p></section></article>\n<article id=\"entry-dgp-14612\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξοχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3373 na letra ε · nº geral 14612</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que ultrapassa a, gen. ou dat.; proeminente; saliente: ἔ. τινὸς κεφαλήν hom. que ultrapassa alguém por uma cabeça, μέγ᾽ ἔ. τινός hom. superior a alguém ou algo, ἔ. ἡρώεσσιν hom. que se distingue entre os heróis 2 superior; eminente ♦ ἔξοχον e ἔξοχα adv. 3 de modo superior; de modo soberbo; extraordinariamente: ἔξοχ᾽ ἄριστοι hom. os melhores de muitos, ἔξοχον φιλεῖν hom. amar de modo extraordinário, δόσαν ἔξοχα hom. ofereceram dons extraordinários, ἔξοχα πάντων hom. acima de todos, ἔξοχα πλούτου pínd. mais do que riqueza. 〈ἐξέχω〉</p></section></article>\n<article id=\"entry-dgp-14613\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξοχυρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3374 na letra ε · nº geral 14613</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cobrir de fortificações; guarnecer de muros.</p></section></article>\n<article id=\"entry-dgp-14614\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυβρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3375 na letra ε · nº geral 14614</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 explodir de orgulho, de insolência por algo, dat. 2 agir ou tratar com arrogância, ac.: ἐ. εἰς τόδε tuc. chegar a este grau de arrogância, ἐ. εἰς τινά luc. ser arrogante com alguém, ὑπό e gen. ou περί e ac. ou εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-14615\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυγραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3376 na letra ε · nº geral 14615</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 impregnar de umidade 2 dissolver; amolecer.</p></section></article>\n<article id=\"entry-dgp-14616\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυλακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3377 na letra ε · nº geral 14616</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gritar; urrar.</p></section></article>\n<article id=\"entry-dgp-14617\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυπανίσταμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3378 na letra ε · nº geral 14617</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.2 3ª sing. ἐξυπανέστη) erguer-se de, gen.</p></section></article>\n<article id=\"entry-dgp-14618\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξύπερθε</h1><div class=\"entry-meta\"><span>DGP · ordem 3379 na letra ε · nº geral 14618</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. acima. 〈ἐξ, ὕπερθε〉</p></section></article>\n<article id=\"entry-dgp-14619\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυπηρετέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3380 na letra ε · nº geral 14619</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vir em socorro de; prestar assistência a; servir. 〈ἐξ, ὑπηρετέω〉</p></section></article>\n<article id=\"entry-dgp-14620\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυπνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3381 na letra ε · nº geral 14620</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acordar ♦ pas. 2 despertar. 〈ἐξ, ὕπνος〉</p></section></article>\n<article id=\"entry-dgp-14621\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξυπνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3382 na letra ε · nº geral 14621</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. desperto. 〈ἐξ, ὕπνος〉</p></section></article>\n<article id=\"entry-dgp-14622\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυπτιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3383 na letra ε · nº geral 14622</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 virar para trás (os olhos) 2 cair para trás; cair de costas ♦ méd. 3 virar-se ou virar para trás (a cabeça).</p></section></article>\n<article id=\"entry-dgp-14623\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυφαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 3384 na letra ε · nº geral 14623</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐξύφηνα) 1 tecer roupa 2 (abelha) fabricar favo 3 compor canto 4 tramar cilada ♦ méd. 5 tecer para si.</p></section></article>\n<article id=\"entry-dgp-14624\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξυφηγέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3385 na letra ε · nº geral 14624</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">andar à frente; preceder.</p></section></article>\n<article id=\"entry-dgp-14625\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕξω</h1><div class=\"entry-meta\"><span>DGP · ordem 3386 na letra ε · nº geral 14625</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de ἔχω.</p></section></article>\n<article id=\"entry-dgp-14626\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξω</h1><div class=\"entry-meta\"><span>DGP · ordem 3387 na letra ε · nº geral 14626</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. (comp. ἐξωτέρω, superl. ἐξωτάτω) 1 (lugar) fora: ἔξω ἰέναι hom., ἔξω χωρεῖν her. ir para fora, ἔξω βλέπειν dem. olhar para fora, τὰ ἔξω πράγματα tuc. os assuntos relativos ao estrangeiro ♦ prep. 2 (lugar) fora de, gen.: ἔξω χροὸς ἕλκειν hom. tirar fora do corpo, ἔξω γῆς βαλεῖν ésql. expulsar para fora do país, ἔξω αὑτοῦ εἶναι ou γίνεσθαι plat. estar fora de si, οἱ ἔξω τοῦ πράγματος ὄντες dem. os que estão fora da questão, i.e., os que não estão engajados na questão, ἔξω τοῦ λόγου ou τοῦ πράγματος λέγειν dem. falar fora do tema, ἔξω τοῦ φυτεύσαντος sóf. fora do que seria próprio de teu genitor 3 (lugar) além de, ac. ou gen.: ἔξω τὸν Ἑλλήσποντον πλεῖν her. navegar além do Helesponto, ἔξω τῶν βελῶν xen. além dos dardos, ἔξω τοξεύματος tuc. além, i.e., fora do alcance dos dardos, ἡ ἔξω στηλέων θάλασσα her., ou ἡ ἔξω θάλασσα plat. o mar além das colunas de Héracles, i.e., o Oceano (op. ἡ ἐντὸς θάλασσα o mar interior, o Mediterrâneo) 4 fora de; com exceção de; à parte de, gen.; ἔξω ἤ her. exceto 5 (tempo) além de; depois de: ἔξω μέσου ἡμέρας xen. após o meio do dia, ἔξω τῆς ἡλικίας dem. além da idade, ἔξω πέντ᾽ ἐτῶν dem. após cinco anos ♦ οἱ ἔξω 6 os adversários 7 os exilados 8 bíbl. os pagãos; os gentios. 〈ἐξ〉</p></section></article>\n<article id=\"entry-dgp-14627\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξωθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 3388 na letra ε · nº geral 14627</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de fora; do exterior: οἱ ἔξωθεν λόγοι dem. discursos fora do assunto ♦ prep. 2 fora de; no exterior de, gen.: ἔξωθεν δόμων eur. fora da casa, ἐντὸς ἢ ἔξωθεν δόμων eur. no interior ou no exterior da casa 3 fora de; sem: ἔξωθεν ξυμφορᾶς sóf. sem infortúnio, ἔξωθεν δειμάτων eur. sem medo ♦ οἱ ἔξωθεν 4 os de fora, os estrangeiros 5 bíbl. os que estão fora da Igreja; os pagãos ♦ τὰ ἔξωθεν 6 as coisas de fora; o que se passa fora da casa. 〈ἔξω, -θεν〉</p></section></article>\n<article id=\"entry-dgp-14628\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3389 na letra ε · nº geral 14628</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐξώσω, aor. ἐξέωσα; pas. fut. ἐξωσθήσομαι, aor. ἐξεώσθην) 1 fazer sair com violência; expulsar de, gen., em ou para, εἰς e ac.: ἐξωθ. τινὰ γῆς sóf. banir alguém de um país 2 lançar; jogar: ἐξωθ. τὴν πόλιν εἰς χαλεπόν plut. colocar a cidade em dificuldades, ἐξωθ. γλώσσας ὀδύναν sóf. lançar fora da boca palavras que causam dor 3 repudiar; rejeitar 4 reter; impedir: ἐξωσθῆναι ἐς χειμῶνα tuc. ter sido retido até o inverno, ἐξωσθήσομαι εἰπεῖν dem. serei impedido de dizer.</p></section></article>\n<article id=\"entry-dgp-14629\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώκοιτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3390 na letra ε · nº geral 14629</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peixe que dorme fora da água. 〈ἔξω, κοίτη〉</p></section></article>\n<article id=\"entry-dgp-14630\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώλεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3391 na letra ε · nº geral 14630</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruína completa; extermínio. 〈ἐξώλης〉</p></section></article>\n<article id=\"entry-dgp-14631\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώλης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 3392 na letra ε · nº geral 14631</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arruinado; destruído 2 pernicioso; funesto. 〈ἐξόλλυμι〉</p></section></article>\n<article id=\"entry-dgp-14632\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωμίας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3393 na letra ε · nº geral 14632</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que tem os braços nus até os ombros. 〈ἐξ, ὦμος〉</p></section></article>\n<article id=\"entry-dgp-14633\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωμιδοποιΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3394 na letra ε · nº geral 14633</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">confecção de túnica de uma só manga. 〈ἐξωμίς〉</p></section></article>\n<article id=\"entry-dgp-14634\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωμίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3395 na letra ε · nº geral 14634</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 túnica de uma só manga 2 em Roma, túnica sem mangas. 〈ἐξ, ὦμος〉</p></section></article>\n<article id=\"entry-dgp-14635\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωμοσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3396 na letra ε · nº geral 14635</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 declaração de completa ignorância, feita sob juramento, a respeito de uma questão 2 ação de recusar serviço ou incumbência. 〈ἐξόμνυμι〉</p></section></article>\n<article id=\"entry-dgp-14636\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωνέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3397 na letra ε · nº geral 14636</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comprar: ὁ ἐξωνούμενος ésqn. o comprador 2 resgatar: ἐ. χρημάτων τινά artt. resgatar alguém por dinheiro 3 furtar-se a; escapar de, ac.: τοῖς χρήμασι ἐξωνοῦνται τοὺς κινδύνους lís. escapam dos perigos por meio de dinheiro 4 obter; conseguir de alguém, παρά e gen., que, inf.: τρισχιλίων ἐξωνήσατο παρὰ τῶν γονέων μὴ ἀπαχθῆναι luc. por três mil dracmas obteve dos pais não ser levado.</p></section></article>\n<article id=\"entry-dgp-14637\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώπιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3398 na letra ε · nº geral 14637</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fora do alcance da vista; distante de, gen. 〈ἐξ, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-14638\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωριάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3399 na letra ε · nº geral 14638</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">negligenciar. 〈ἐξ, ὤρα〉</p></section></article>\n<article id=\"entry-dgp-14639\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3400 na letra ε · nº geral 14639</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que não é conveniente; intempestivo; deslocado 2 que não é da época; inoportuno; velho; obsoleto 3 que passou a idade de, gen. 〈ἐξ, ὤρα〉</p></section></article>\n<article id=\"entry-dgp-14640\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώστης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 3401 na letra ε · nº geral 14640</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que repudia; que expulsa 2 impetuoso (vento). 〈ἐξωθέω〉</p></section></article>\n<article id=\"entry-dgp-14641\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξωτάτω, ἐξωτέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3402 na letra ε · nº geral 14641</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔξω.</p></section></article>\n<article id=\"entry-dgp-14642\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξώτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3403 na letra ε · nº geral 14642</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. mais externo; mais afastado. 〈ἔξω〉</p></section></article>\n<article id=\"entry-dgp-14643\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕο</h1><div class=\"entry-meta\"><span>DGP · ordem 3404 na letra ε · nº geral 14643</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. οὗ.</p></section></article>\n<article id=\"entry-dgp-14644\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοι</h1><div class=\"entry-meta\"><span>DGP · ordem 3405 na letra ε · nº geral 14644</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. opt. ép. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-14645\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 3406 na letra ε · nº geral 14645</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. jôn. de οὗ.</p></section></article>\n<article id=\"entry-dgp-14646\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοιγμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 3407 na letra ε · nº geral 14646</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. sinc. de ἔοικα.</p></section></article>\n<article id=\"entry-dgp-14647\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοικα,</h1><div class=\"entry-meta\"><span>DGP · ordem 3408 na letra ε · nº geral 14647</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. εἶκα perf. com sent. de pres. (part. ἐοικώς e εἰκώς, m.-q.-perf. ἐῴκειν, át. ᾔκειν) 1 ser parecido com; assemelhar-se a alguém, dat., em algo, ac.: ἀθανάτῃσι θεῇς εἰς ὦπα ἔοικεν hom. assemelhava-se no aspecto deusas imortais 2 ter aparência de; aparentar; parecer, com adj. ou part. no dat.: ἔοικε τοῦτ᾽ ἀτόπῳ plat. isso parece um absurdo, ἔοικας τὴν εὐδαιμονίαν οἰομένῳ τρυφὴν εἶναι xen. tens aparência de quem pensa que a felicidade é luxúria 3 ter o aspecto de; dar a impressão de; parecer, inf. ou part.: τὸν ἄνδρα ἔοικεν ὕπνος... ἕξειν sóf. parece que o sono o dominará, ἐοίκατε ἡδόμενοι xen. pareceis contentes; impes. ὡς ἔοικε como parece, ao que parece; eu suponho; provavelmente; em respostas, parece que sim; é provável 4 ter a impressão de que, inf.: ἔοικα θρηνεῖν μάτην ésql. tenho a impressão de que me lamento em vão 5 parecer bom; convir a alguém, dat.: τὸ μὲν ἀπιέναι οὐδενὶ καλῷ ἔοικε xen. a deserção não convém a nenhum homem valente 6 impes. ἔοικε é conveniente; é bom: οὔ σε ἔοικε, κακὸν ὣς, δειδίσσεσθαι hom. não convém que sintas medo, como um covarde ♦ ἐοικώς, át. εἰκώς, jôn. οἰκώς, υῖα, ός part. perf. 7 assemelhado; semelhante a, dat.: ὁ φόβος ἦν οὐδενὶ ἐοικώς tuc. o pavor a nada era semelhante, i.e., sem igual, ímpar 8 conveniente: μῦθοί γε ἐοικότες hom. palavras convenientes 9 razoável; sensato: εἰκότες λόγοι plat. palavras sensatas 10 verossímil; provável: τὸ οὐκ ἐοικός tuc. o improvável ♦ εἰκός part. n. 11 justo; natural; conveniente: εἰκός ἐστι sóf. é natural, ὡς εἰκός sóf. ou ὡς οἰκός her. ou ὡς τὸ εἰκός tuc. como é natural ♦ τὸ εἰκός ou τὸ οἰκός 12 a probabilidade: τὰ οἰκότα her. as probabilidades, κατὰ τὸ εἰκός ou ἐκ τοῦ εἰκότος tuc. conforme a probabilidade, παρὰ τὸ εἰκός tuc. contra a expectativa ♦ pas. (só perf. 3a sing. ἤϊκται, e m.-q.-perf. 3a sing. ἤϊκτο e ἔϊκτο) 13 ser parecido com; assemelhar-se a, dat.: δέμας δ᾽ἤϊκτο γυναικί hom. de corpo, assemelhava-se a uma mulher.</p></section></article>\n<article id=\"entry-dgp-14648\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐοικότως,</h1><div class=\"entry-meta\"><span>DGP · ordem 3409 na letra ε · nº geral 14648</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. εἰκότως adv. 1 semelhantemente a, dat. 2 como era de esperar; verossimilhantemente 3 como é natural; naturalmente: οὐκ εἰκότως tuc. sem razão. 〈ἔοικα〉</p></section></article>\n<article id=\"entry-dgp-14649\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐοικώς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 3410 na letra ε · nº geral 14649</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔοικα.</p></section></article>\n<article id=\"entry-dgp-14650\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑοῖο</h1><div class=\"entry-meta\"><span>DGP · ordem 3411 na letra ε · nº geral 14650</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de ἑός.</p></section></article>\n<article id=\"entry-dgp-14651\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοις</h1><div class=\"entry-meta\"><span>DGP · ordem 3412 na letra ε · nº geral 14651</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. opt. ép., ἐοῖσα part. pres. fem. dór., de εἰμί.</p></section></article>\n<article id=\"entry-dgp-14652\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔολπα</h1><div class=\"entry-meta\"><span>DGP · ordem 3413 na letra ε · nº geral 14652</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔλπω.</p></section></article>\n<article id=\"entry-dgp-14653\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔον</h1><div class=\"entry-meta\"><span>DGP · ordem 3414 na letra ε · nº geral 14653</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª sing. impf. ép., ἐόν part. pres. n. jôn., de εἰμί.</p></section></article>\n<article id=\"entry-dgp-14654\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑόν</h1><div class=\"entry-meta\"><span>DGP · ordem 3415 na letra ε · nº geral 14654</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. n. e masc. de ἑός.</p></section></article>\n<article id=\"entry-dgp-14655\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔοργα</h1><div class=\"entry-meta\"><span>DGP · ordem 3416 na letra ε · nº geral 14655</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔρδω.</p></section></article>\n<article id=\"entry-dgp-14656\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐόργεε</h1><div class=\"entry-meta\"><span>DGP · ordem 3417 na letra ε · nº geral 14656</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. m.-q.-perf. jôn. de ἔρδω.</p></section></article>\n<article id=\"entry-dgp-14657\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3418 na letra ε · nº geral 14657</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἑώρταζον, fut. ἑορτάσω, aor. ἑώρτασα, perf. ἑώρτακα) 1 celebrar uma festa: ἑορ. θεῷ luc. celebrar festa em honra de um deus, ἑορ. ἑορτάς xen. celebrar festas 2 comemorar com festas; festejar: ἑορ. νίκην plut. festejar uma vitória. 〈ἑορτή〉</p></section></article>\n<article id=\"entry-dgp-14658\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτάσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3419 na letra ε · nº geral 14658</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de festa ♦ τὰ ἑορτάσιμα 2 preparativos de uma festa. 〈ἑορτάζω〉</p></section></article>\n<article id=\"entry-dgp-14659\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑόρτασις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3420 na letra ε · nº geral 14659</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">celebração de uma festa; solenidade; festa. 〈ἑορτάζω〉</p></section></article>\n<article id=\"entry-dgp-14660\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3421 na letra ε · nº geral 14660</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἑόρτασις.</p></section></article>\n<article id=\"entry-dgp-14661\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑορτή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3422 na letra ε · nº geral 14661</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 festa: ἑορτὴν ἄγειν, ἀνάγειν, ποιεῖν ou ἑορτάς ἑορτάζειν celebrar uma festa em honra de, dat. 2 alegria; divertimento.</p></section></article>\n<article id=\"entry-dgp-14662\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑός, ἑή, ἑόν</h1><div class=\"entry-meta\"><span>DGP · ordem 3423 na letra ε · nº geral 14662</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e dór., rar. jôn. 1 pron. poss. ou refl. de 3ª p. seu; sua; com αὐτοῦ: ἑῷ αὐτοῦ θυμῷ hom. dentro de seu próprio coração, ἑοὶ αὐτοῦ θῆτες hom. seus próprios servos 2 pron. refl. de 1ª ou 2ª sing. ou pl., meu; minha; nosso; nossa; teu; tua; vosso; vossa.</p></section></article>\n<article id=\"entry-dgp-14663\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐοῦσα</h1><div class=\"entry-meta\"><span>DGP · ordem 3424 na letra ε · nº geral 14663</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. pres. fem. jôn. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-14664\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγάλλομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3425 na letra ε · nº geral 14664</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) gloriar-se de; regozijar-se de; exultar com, dat. ou ἐπί e dat.</p></section></article>\n<article id=\"entry-dgp-14665\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγανακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3426 na letra ε · nº geral 14665</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indignar-se com; irritar-se com, dat.</p></section></article>\n<article id=\"entry-dgp-14666\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγείλῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 3427 na letra ε · nº geral 14666</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. aor. subj. ép. de ἐπαγγέλλω.</p></section></article>\n<article id=\"entry-dgp-14667\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγελία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3428 na letra ε · nº geral 14667</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 prescrição; ordem 2 anúncio; notícia 3 promessa 4 Jur. intimação para a docimacia dos oradores, processo judicial para decidir o direito de um homem, privado parcial ou totalmente de seus direitos civis, de falar na assembléia ou no tribunal. 〈ἐπαγγέλλω〉</p></section></article>\n<article id=\"entry-dgp-14668\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγέλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 3429 na letra ε · nº geral 14668</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπαγγελῶ, aor. ἐπήγγειλα, perf. ἐπήγ­γελκα) 1 anunciar; declarar; proclamar a alguém, dat., algo, ac. ou inf. ou or. conj. (ὡς): ἐπ. σπονδάς tuc. anunciar uma trégua, ἐπ. πόλεμον plat. declarar guerra 2 Jur. intimar; citar: δοκιμασίαν ἐπ. intimar para a docimacia (do direito de falar em público, na assembléia ou no tribunal), πρὸς τοὺς θεσμοθέτας ἐπ. dem. citar diante dos tesmotetas 3 ordenar; prescrever algo, ac. ou inf.: στρατιὰν ἐς τοὺς ξυμμάχους ἐπ. tuc. exigir dos aliados que forneçam seus contingentes 4 solicitar; pedir: τοῖς θεοῖς εὐχὰς ἐπ. ésql. dirigir preces aos deuses 5 oferecer; prometer algo, ac., a alguém, dat. ♦ méd. 6 fazer proclamar; declarar 7 ordenar 8 fazer profissão de; professar: ἐπ. ἀρετήν xen. professar virtude, ἐπ. διδάσκειν artt. fazer profissão de ensinar.</p></section></article>\n<article id=\"entry-dgp-14669\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγγελμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3430 na letra ε · nº geral 14669</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 anúncio 2 declaração; promessa 3 pl. comícios, em Roma. 〈ἐπαγγέλλω〉</p></section></article>\n<article id=\"entry-dgp-14670\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγγελτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3431 na letra ε · nº geral 14670</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que promete muito 2 presunçoso. 〈ἐπαγγέλλω〉</p></section></article>\n<article id=\"entry-dgp-14671\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3432 na letra ε · nº geral 14671</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">reunir.</p></section></article>\n<article id=\"entry-dgp-14672\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγερσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3433 na letra ε · nº geral 14672</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de reunir forças contra um inimigo. 〈ἐπαγείρω〉</p></section></article>\n<article id=\"entry-dgp-14673\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγην</h1><div class=\"entry-meta\"><span>DGP · ordem 3434 na letra ε · nº geral 14673</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 pas. de πήγνυμι.</p></section></article>\n<article id=\"entry-dgp-14674\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3435 na letra ε · nº geral 14674</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐπάγω.</p></section></article>\n<article id=\"entry-dgp-14675\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγλαΐζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3436 na letra ε · nº geral 14675</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alegrar 2 embelezar; adornar ♦ méd. 3 regozijar-se com; estar orgulhoso de, dat.</p></section></article>\n<article id=\"entry-dgp-14676\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγρυπνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 3437 na letra ε · nº geral 14676</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">velar por; estar vigilante, dat. 〈ἐπί, ἀγρυ­πνέω〉</p></section></article>\n<article id=\"entry-dgp-14677\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 3438 na letra ε · nº geral 14677</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπῆγον, fut. ἐπάξω, aor.2 ἐπήγαγον; pas. fut. ἐπαχθήσομαι, aor. ἐπήχθην) 1 levar em, para ou sobre; aplicar algo, ac., a, dat.: τὴν διάνοιαν ἐπ. θεάμασιν plut. aplicar a mente a visões, ἐπ. κέντρον πώλοις eur. aplicar o aguilhão nos cavalos, νόσους γῆράς τε ἐπ. plat. levar doenças e velhice, τοῖσι ἐπήγαγε πῆμα hes. infligiu-lhes uma desgraça 2 conduzir; induzir; persuadir alguém, ac., a algo, ἐπί e ac., ou inf.: ἐπ. ποιεῖν τι eur. levar a fazer alguma coisa 3 levar em acréscimo; adicionar algo, ac., a, dat.: ἐπ. πέντε ἡμέρας παρὲξ τοῦ ἀριθμοῦ her. adicionar cinco dias ao número normal, ἐπ. τῷ λόγῳ ἔργον plut. juntar a ação à palavra 4 conduzir contra; impelir algo, ac., contra algo ou alguém, dat.: ἐπ. στρατιάν her., στρατόν plut. conduzir uma expedição, Ἀργείους ἐπ. τοῖσδε δώμασιν eur. guiar os argivos contra este palácio, ἐπάγει δουρικλύτοις ἀνδράσι τοξόδαμνον Ἄρη ésql. conduz contra varões famosos nas lanças Ares, domador das flechas 5 Lóg. fazer uma indução; raciocionar por indução ♦ méd. (fut. ἐπάξομαι, aor.2 ἐπηγαγόμην) 6 fazer vir para si: ἐπ. ἐκ θαλάττης ὧν δέονται tuc. fazer chegar por mar aquilo de que se necessita, ἐπ. τὸ πλῆθος tuc. atrair a multidão, ἐπ. τινὰς συγχωρῆσαι tuc. levar os adversários a conceder (aquilo que se pede) 7 levar consigo 8 apresentar para si; chamar; citar: ἐπ. μαρτύρια xen. apresentar testemunho.</p></section></article>\n<article id=\"entry-dgp-14678\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγωγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3439 na letra ε · nº geral 14678</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de trazer em, para ou contra 2 importação; introdução 3 ação de trazer socorro; ajuda 4 evocação (das divindades infernais) 5 movimento de tropas; marcha; ataque 6 tard. cativeiro. 〈ἐπάγω〉</p></section></article>\n<article id=\"entry-dgp-14679\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγώγιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 3440 na letra ε · nº geral 14679</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">introduzido; importado. 〈ἐπαγωγός〉</p></section></article>\n<article id=\"entry-dgp-14680\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγωγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 3441 na letra ε · nº geral 14680</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que traz para si; que atrai envolvendo ou seduzindo 2 atraente; persuasivo 3 que se concilia com alguém, ἐπί e gen. 4 que leva pela persuasão a, πρός e ac. ♦ τὸ ἐπαγωγόν 5 a arte da persuasão. 〈ἐπάγω〉</p></section></article>\n<article id=\"entry-dgp-14681\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαγωνίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3442 na letra ε · nº geral 14681</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐπηγωνισάμην) 1 lutar apoiando-se sobre, dat.: ἐπ. τεκμηρίοις plut. apoiar-se sobre testemunho para sustentar uma opinião 2 lutar de novo contra alguém, dat. 3 lutar por, dat.: ἐπηγωνίσατο ταῖς νίκαις plut. lutou pelas vitórias 4 retrucar.</p></section></article>\n<article id=\"entry-dgp-14682\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπᾴδω</h1><div class=\"entry-meta\"><span>DGP · ordem 3443 na letra ε · nº geral 14682</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(inf. aor. ἐπᾷσαι) 1 acompanhar cantando: ἐπ. ᾠδὰν χόρῳ eur. acompanhar com dança o canto 2 cantar algo, ac., para fascinar alguém, dat.; fazer alguém, dat., ouvir encantamentos 3 usar encantamentos ou feitiços.</p></section></article>\n<article id=\"entry-dgp-14683\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαείδω</h1><div class=\"entry-meta\"><span>DGP · ordem 3444 na letra ε · nº geral 14683</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἐπᾴδω.</p></section></article>\n<article id=\"entry-dgp-14684\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπάειραν</h1><div class=\"entry-meta\"><span>DGP · ordem 3445 na letra ε · nº geral 14684</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. de ἐπαείρω.</p></section></article>\n<article id=\"entry-dgp-14685\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 3446 na letra ε · nº geral 14685</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. = ἐπαίρω.</p></section></article>\n<article id=\"entry-dgp-14686\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπαθλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 3447 na letra ε · nº geral 14686</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prêmio da luta. 〈ἐπί, ἆθλον〉</p></section></article>\n<article id=\"entry-dgp-14687\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔπαθον</h1><div class=\"entry-meta\"><span>DGP · ordem 3448 na letra ε · nº geral 14687</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 de πάσχω.</p></section></article>\n<article id=\"entry-dgp-14688\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαθροίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 3449 na letra ε · nº geral 14688</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">reunir-se em uma multidão compacta.</p></section></article>\n<article id=\"entry-dgp-14689\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3450 na letra ε · nº geral 14689</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπαιάξω) lamentar-se; gemer sobre, dat.</p></section></article>\n<article id=\"entry-dgp-14690\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπαιγίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 3451 na letra ε · nº geral 14690</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἐπαιγίσω) lançar-se com impetuosidade sobre ou em, dat. 〈ἐπί, αἰγίς〉</p></section></article>\n";
